<div class="page-intro"><div><h2>ประวัติคำขอและการยืม</h2><p>ติดตามสถานะตั้งแต่ส่งคำขอ อนุมัติ ไปจนถึงคืนครุภัณฑ์</p></div><a class="btn btn-primary" href="<?=e(url('student/borrow.php'))?>">+ ยืมครุภัณฑ์</a></div><div class="card"><div class="table-tools"><div class="table-search"><input type="search" placeholder="ค้นหารายการของฉัน…" data-table-search="#myTable"></div><span class="table-meta"><?=count($rows)?> รายการ</span></div><div class="table-wrap"><table class="data-table" id="myTable"><thead><tr><th>ครุภัณฑ์</th><th>วัตถุประสงค์</th><th>วันที่ส่งคำขอ</th><th>สถานะ</th><th>วันที่คืน</th><th>จัดการ</th></tr></thead><tbody><?php if(!$rows):?><tr data-empty><td colspan="6"><div class="empty-state"><div class="empty-icon">▤</div><h3>ยังไม่มีคำขอ</h3><p>เริ่มต้นโดยเลือกครุภัณฑ์ที่ต้องการยืม</p></div></td></tr><?php else:foreach($rows as $r):$img=device_image($r);?><tr><td><div class="device-cell"><?php if($img):?><img class="device-thumb" src="<?=e($img)?>" alt=""><?php else:?><span class="device-placeholder">ET</span><?php endif;?><span><b class="cell-title"><?=e($r['d_name'])?></b><small class="cell-sub"><?=e($r['d_id'])?> • <?=e($r['t_name']?:'-')?></small></span></div></td><td><?=e($r['ser_reason'])?></td><td><?=e(thai_date($r['ser_request_date']?:$r['ser_datesave'],true))?></td><td><?=badge_service($r['ser_status'])?></td><td><?=e(thai_date($r['ser_date_return']))?></td><td><?php if($r['ser_status']==='pending'):?><form method="post" data-confirm="ยกเลิกคำขอยืมรายการนี้หรือไม่?" data-confirm-title="ยกเลิกคำขอ"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=e($r['ser_id'])?>"><button class="btn btn-danger-soft btn-sm">ยกเลิกคำขอ</button></form><?php else:?><span class="muted">-</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php render_footer();?>
